args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birth ?death ?ageDays WHERE {
  VALUES ?person { dbr:Ahmed_Mamsa dbr:Lesley_Woods }
  ?person dbo:birthDate ?birth .
  ?person dbo:deathDate ?death .
  BIND( ((YEAR(?death) - YEAR(?birth))*365 + (MONTH(?death) - MONTH(?birth))*30 + (DAY(?death) - DAY(?birth))) AS ?ageDays )
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel) = 'en') }
}
ORDER BY DESC(?ageDays)

